// Extract leadgen_id from Meta webhook payload
const body = $input.item.json.body || $input.item.json;
const change = body.entry?.[0]?.changes?.[0];
const leadgenId = change?.value?.leadgen_id || body.leadgen_id || "";
const formId = change?.value?.form_id || body.form_id || "";
const pageId = change?.value?.page_id || body.page_id || "";

if (!leadgenId) {
  // If testing payload with raw data
  return [{
    json: {
      leadgenId: "DEMO_LEAD",
      fullName: body.fullName || "Lead Client",
      phone: body.phone || "923270831470",
      city: body.city || "Lahore",
      sector: body.sector || "Real Estate",
      budget: body.budget || "PKR 1 Crore"
    }
  }];
}

return [{
  json: {
    leadgenId,
    formId,
    pageId,
    timestamp: new Date().toISOString()
  }
}];

const response = $input.item.json;
const fields = response.field_data || [];

let fullName = "Valued Client";
let rawPhone = "";
let email = "";
let city = "Pakistan";
let sector = "Real Estate / Furniture / Events";
let budget = "Flexible";

for (const f of fields) {
  const name = f.name.toLowerCase();
  const val = f.values?.[0] || "";
  if (name.includes("full_name") || name.includes("name")) fullName = val;
  if (name.includes("phone") || name.includes("number")) rawPhone = val;
  if (name.includes("email")) email = val;
  if (name.includes("city")) city = val;
  if (name.includes("sector") || name.includes("service") || name.includes("category")) sector = val;
  if (name.includes("budget") || name.includes("price")) budget = val;
}

// Normalize phone
let phone = String(rawPhone).replace(/[^0-9]/g, "");
if (phone.startsWith("03")) phone = "92" + phone.substring(1);
else if (phone.startsWith("3") && phone.length === 10) phone = "92" + phone;

if (!phone && $('Extract Leadgen ID').item.json.phone) {
  phone = $('Extract Leadgen ID').item.json.phone;
  fullName = $('Extract Leadgen ID').item.json.fullName || fullName;
  sector = $('Extract Leadgen ID').item.json.sector || sector;
}

const leadId = `FB-LEAD-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

return [{
  json: {
    leadId,
    fullName,
    phone,
    email,
    city,
    sector,
    budget,
    source: "facebook_lead_ads",
    createdAt: new Date().toISOString()
  }
}];

